const { createHash } = require('crypto');
const envelope = $input.first().json;
if (envelope.execution_mode !== 'OFFLINE_EVAL' || envelope.external_effects_allowed !== false) throw new Error('WF-02 aceita somente OFFLINE_EVAL sem efeitos externos');
const required = [envelope.event?.event_id, envelope.event?.tenant_id, envelope.correlation_id, envelope.run_id, envelope.idempotency_key, envelope.input_hash, envelope.release_id, envelope.event?.received_at];
if (required.some((value) => !value)) throw new Error('Envelope incompleto para persistência idempotente');
const material = [envelope.input_hash, envelope.correlation_id, 'REGISTRATION_ATTEMPT'].join('|');
return [{ json: { ...envelope, registration_audit_hash: `sha256:${createHash('sha256').update(material, 'utf8').digest('hex')}` } }];

const row = $input.first().json;
const envelope = typeof row.envelope === 'string' ? JSON.parse(row.envelope) : row.envelope;
if (!envelope || !row.registration_status) throw new Error('Banco não retornou o resultado do registro');
delete envelope.registration_audit_hash;
return [{ json: { ...envelope, registration: { event_id: row.event_id, registration_status: row.registration_status, technical_status: row.technical_status, is_new: row.is_new === true, artifacts_registered: Number(row.artifacts_registered ?? 0), audit_id: Number(row.audit_id), registered_at: row.registered_at } } }];
